 "。抖音/微博/微信互动量需开放平台密钥且条款禁止抓取，故本页按「关键词命中数」排序，不展示热度值与参与量。": "。抖音/微博/微信のインタラクション量はオープンプラットフォームのキーが必要で、規約で取得が禁止されているため、本ページは「キーワードヒット数」順に並べ替え、熱度値と参加量は表示していません。",
 "全国底图 · 聚焦山东 · 各市 A 级景区数量热力（普查口径）+ 重点监测景点客流点位（圆点按景区等级着色）；点圆点看客流画像，单击地市切换分析范围并细分县区": "全国ベースマップ · 山東にフォーカス · 各市A級景区数量のヒートマップ（全面調査基準）+ 重点モニタリング観光スポットの人流通ポイント（ドットは景区等級で着色）；ドットをクリックで人流プロファイル、地市をクリックで分析範囲を切替え県区を細分化",
 "全国底图 · 聚焦山东 · 各市按固定彩色区分、五颜六色（颜色只作区分，范围外地市灰显，数量见图上数字）+ 收录美食碗形标（按类别着色）；点碗形标定位到所属县区，单击地市切换分析范围并细分县区": "全国ベースマップ · 山東にフォーカス · 各市を固定色で色分けしカラフルに表示（色は区分用のみ、範囲外の地市はグレー表示、数量は図上の数字を参照）+ 収録グルメのどんぶり形マーク（カテゴリ別に着色）；どんぶり形マークをクリックで所属県区に定位、地市をクリックで分析範囲を切替え県区を細分化",
 "全国底图 · 聚焦山东 · 各市自然保护区数量热力 + 保护区叶形标（按等级着色）与物种监测点；点叶形标看保护区详情，单击地市切换分析范围并细分县区": "全国ベースマップ · 山東にフォーカス · 各市自然保護区数量のヒートマップ + 保護区の葉形マーク（等級別に着色）と種モニタリング点；葉形マークをクリックで保護区詳細、地市をクリックで分析範囲を切替え県区を細分化",
 "全国底图 · 聚焦山东省 · 颜色越暖表示旅游热度越高 · 单位：万人次 · 统计周期：近30日": "全国ベースマップ · 山東省にフォーカス · 色が暖かいほど観光熱度が高い · 単位：万人回 · 集計期間：直近30日",
 "叶形标 = 保护区（按等级着色）；圆环 = 物种监测点（与保护区同址布设，按物种等级着色）": "葉形マーク = 保護区（等級別に着色）；リング = 種モニタリング点（保護区と同地点に設置、種の等級別に着色）",
 "按名录「申报地区」归属到县区，圆点大小 = 项目数（仅统计能归到县区的项目）；点左侧清单里的项目可定位到该县区。": "名録の「申報地区」で県区に帰属、ドットの大きさ = プロジェクト数（県区に帰属できるプロジェクトのみを集計）；左側のリストのプロジェクトをクリックすると当該県区に定位できます。",
 "清单为平台整理的山东饮食文化条目（鲁菜名菜 / 地方名吃 / 地理标志农产品 / 非遗美食），": "リストはプラットフォームが整理した山東の食文化項目です（魯菜名菜 / ご当地グルメ / 地理的表示農産品 / 無形文化遺産グルメ）、",
 "游客整体评价较好，重点集中在景观体验、服务设施与交通便利性；高峰时段存在排队拥堵反馈。": "観光客の全体的な評価は良好で、主に景観体験、サービス施設、交通の利便性に集中しています；ピーク時間帯には行列や混雑のフィードバックがあります。",
 "范围内灾害风险指数 = 气象实况 + 近十年地震活动（两项为真实抓取数据）+ 地灾隐患 / 人流预警 / 水情监测（演示）": "範囲内の災害リスク指数 = 気象実況 + 直近10年の地震活動（2項目は実際に取得したデータ）+ 地質災害リスク / 人流警報 / 水情モニタリング（デモ）",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），未达到分级阈值（<3% 且 <2 条）": "範囲内（{scope}）の直近 {n} 件の報道のうち、語彙表でネガティブと判定されたのは {negative} 件（{share}%）、レベル別閾値には未到達（<3% かつ <2 件）",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），达到中等级阈值（≥8% 或 ≥4 条）": "範囲内（{scope}）の直近 {n} 件の報道のうち、語彙表でネガティブと判定されたのは {negative} 件（{share}%）、中レベルの閾値に到達（≥8% または ≥4 件）",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），达到偏低阈值（≥3% 或 ≥2 条）": "範囲内（{scope}）の直近 {n} 件の報道のうち、語彙表でネガティブと判定されたのは {negative} 件（{share}%）、やや低い閾値に到達（≥3% または ≥2 件）",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），达到高等级阈值（≥15% 或 ≥8 条）": "範囲内（{scope}）の直近 {n} 件の報道のうち、語彙表でネガティブと判定されたのは {negative} 件（{share}%）、高レベルの閾値に到達（≥15% または ≥8 件）",
