 "南四湖生态红线": "南四湖生態レッドライン",
 "济南三大名胜之首，趵突泉居七十二名泉之冠，三窟并发、四季恒温，素有「天下第一泉」之称。": "済南三大名所の筆頭で、趵突泉は七十二名泉の頂点に立ち、三つの泉孔が同時に湧き、四季を通じて水温が一定で、古くから「天下第一泉」と呼ばれています。",
 "济南本地": "済南地元",
 "五岳之首，世界文化与自然双遗产，主峰玉皇顶海拔 1545 米，历代帝王封禅告祭之地。": "五岳の筆頭で世界文化・自然複合遺産、主峰の玉皇頂は標高 1,545 m、歴代の帝王が封禅の儀を行った地です。",
 "孔庙、孔府、孔林合称「三孔」，世界文化遗产，是儒家文化最完整的实物遗存。": "孔子廟、孔府、孔林は合わせて「三孔」と呼ばれ、世界文化遺産で、儒家文化を最も完全に伝える実物遺存です。",
 "山西": "山西省",
 "黄河入海处的新生湿地，芦花飞雪、河海交汇，是东方白鹳、黑嘴鸥等珍禽的繁殖地。": "黄河が海に注ぐ地の新生湿地で、アシの花が雪のように舞い、川と海が交わり、コウノトリやクロハシユリカモメなど貴重な鳥の繁殖地です。",
 "由济南众泉汇流而成的天然湖泊，「四面荷花三面柳，一城山色半城湖」即咏此处。": "済南の泉水が集まってできた天然湖で、「四方はハス、三方の岸は柳、街の半分は山の色、半分は湖」とうたわれた景勝地です。",
 "济南三大名胜之一，古称历山，隋代崖壁造像千余尊，登顶可俯瞰泉城全景。": "済南三大名所の一つで、古くは歴山と呼ばれ、隋代の崖壁に千余体の仏像が刻まれ、山頂からは泉の都の全景を一望できます。",
 "南四湖中面积最大的湖泊湿地，荷花芦苇连片，也是南水北调东线的重要调蓄湖泊。": "南四湖で最大の湖沼湿地で、ハスとアシが連なり、南水北調東線の重要な調節湖でもあります。",
 "《水浒传》故事发生地，梁山寨、忠义堂等遗迹尚存，是水浒文化旅游的核心景区。": "『水滸伝』の舞台で、梁山の砦や忠義堂などの遺跡が残り、水滸文化観光の中核景区です。",
 "有「旱码头」之称的周村大街，保存完好的明清商业街市，瑞蚨祥等老字号的发源地。": "「陸の港」と呼ばれた周村大街は、明清時代の商業街が良好に保存され、瑞蚨祥など老舗の起源地です。",
 "以《孙子兵法》为主题的仿古建筑群，位于兵圣孙武故里惠民县，是鲁北文旅地标。": "『孫子兵法』をテーマにした擬古建築群で、兵法の聖人・孫武の故郷である惠民県にあり、魯北の文化観光ランドマークです。",
